<?php use backend\models\KrsRegistration;use yii\helpers\{Html,Url};$this->title='Kartu Rencana Studi';?>
<div class="d-flex justify-content-between mb-3"><div><h1 class="mb-0">Kartu Rencana Studi</h1><span class="text-muted">Administrasi KRS Mahasiswa</span></div><div><?=Html::a('Kembali ke Daftar',['index'],['class'=>'btn btn-primary'])?> <?=Html::a('<i class="fas fa-list"></i> Pilih Mata Kuliah',['courses','id'=>$model->id],['class'=>'btn btn-success'])?> <?=Html::button('<i class="fas fa-check"></i> Validasi KRS',['class'=>'btn btn-warning','id'=>'validate-krs','disabled'=>$model->status===KrsRegistration::STATUS_VALIDATED])?></div></div><div class="card card-success card-outline"><div class="card-body"><div class="p-3 mb-3" style="background:#eef6ff"><div class="row"><div class="col-md-6"><strong>NIM:</strong> <?=Html::encode($model->student->student_nationality_number)?><br><strong>Nama:</strong> <?=Html::encode($model->student->user->name)?><br><strong>Program Studi:</strong> <?=Html::encode($model->studyProgram->name)?></div><div class="col-md-6"><strong>Periode:</strong> <?=Html::encode($model->academic_period)?><br><strong>Semester:</strong> <?=$model->semester?><br><strong>Status:</strong> <?=KrsRegistration::statusOptions()[$model->status]?></div></div></div><table class="table table-bordered"><thead class="thead-dark"><tr><th>No</th><th>Kode</th><th>Nama Mata Kuliah</th><th>Nama Kelas</th><th>SKS</th><th>Jadwal</th><th>Aksi</th></tr></thead><tbody><?php foreach($model->items as $i=>$item):$class=$item->lectureClass;?><tr><td><?=$i+1?></td><td><?=Html::encode($class->curriculum->subject->code)?></td><td><?=Html::encode($class->curriculum->subject->name)?></td><td><?=Html::encode($class->name)?></td><td><?=$class->curriculum->subject->credits?></td><td><?=$class->scheduleLabel?></td><td><?=Html::button('<i class="fas fa-trash"></i>',['class'=>'btn btn-danger btn-sm js-remove-course','data-url'=>Url::to(['remove-course','id'=>$model->id,'item_id'=>$item->id])])?></td></tr><?php endforeach?><?php if(!$model->items):?><tr><td colspan="7" class="text-center text-muted">Mahasiswa belum mengambil KRS</td></tr><?php endif?><tr class="font-weight-bold"><td colspan="4">Total SKS</td><td><?=$model->totalCredits?></td><td colspan="2"></td></tr><tr class="font-weight-bold"><td colspan="4">Batas SKS</td><td><?=$model->maximum_credits?></td><td colspan="2"></td></tr></tbody></table></div></div>
<?php $validate=Url::to(['validate','id'=>$model->id]);$js=<<<'JS'
$('#validate-krs').on('click',function(){Swal.fire({title:'Validasi KRS?',text:'Pastikan pilihan mata kuliah sudah benar.',icon:'question',showCancelButton:true,confirmButtonText:'Ya, Validasi',cancelButtonText:'Batal'}).then(function(r){if(!r.isConfirmed)return;$.post('__VALIDATE__',{_csrf:yii.getCsrfToken()}).done(function(x){Swal.fire(x.success?'Berhasil':'Gagal',x.message,x.success?'success':'error').then(function(){if(x.success)location.reload();});});});});$(document).on('click','.js-remove-course',function(){var url=$(this).data('url');Swal.fire({title:'Hapus mata kuliah?',icon:'warning',showCancelButton:true,confirmButtonText:'Ya, Hapus'}).then(function(r){if(!r.isConfirmed)return;$.post(url,{_csrf:yii.getCsrfToken()}).done(function(){location.reload();});});});
JS;$this->registerJs(str_replace('__VALIDATE__',$validate,$js));?>
